                                  '/// Uses the existing draft identity, dirty-state guard and immutable '
                                  'review.\n'
                                  '@MainActor\n'
                                  'private struct MerchantTemplateParticipationPlanFields: View {\n'
                                  '    @ObservedObject var model: MerchantOperationsViewModel\n'
                                  '    private var template: MerchantNodeTemplate? {\n'
