                                  ')\n'
                                  '\n'
                                  '\n'
                                  'def assert_read_transport_contract(test, source):\n'
                                  '    # Scope to the contradictory-outcome test, not assertions in another '
                                  'method.\n'
                                  "    method = source.split('func "
                                  "testReadTransportRejectsContradictoryOutcomeWithoutMutation()', 1)[1]\n"
                                  "    method = without_comments(method.split('\\n    func ', 1)[0])\n"
                                  '    for assertion in READ_TRANSPORT_ASSERTIONS:\n'
                                  '        test.assertIn(assertion, method)\n'
                                  '    test.assertIn(\'fields["processing"] = .string("REFUNDED")\', '
                                  'method)\n'
                                  '    test.assertIn(\'row["refunded"] = .bool(false)\', method)\n'
                                  "    test.assertIn('try await service.document(.refund(.init(62001)), "
